def validate_basic_schema(config: dict) -> None:
    """First pass of validation, without third-party schema.

    This mirrors the structure of the former ``schema`` definitions and
    raises :class:`SchemaError` on the same kinds of problems.
    """

    if not isinstance(config, dict):
        raise SchemaError("config should be a dict")

    # version
    version = _require(config, "version", dict, "")
    current = _require(version, "current", str, "version.")
    regex = _require(version, "regex", str, "version.")

    # Validate regex (re.VERBOSE to keep previous behavior)
    re.compile(regex, re.VERBOSE)

    # git
    git = _require(config, "git", dict, "")
    _require(git, "message_template", str, "git.")
    _require(git, "tag_template", str, "git.")
    atomic_push = git.get("atomic_push", False)
    if atomic_push is not False and not isinstance(atomic_push, bool):
        raise SchemaError("git.atomic_push has invalid type")
    sign = git.get("sign", False)
    if sign is not False and not isinstance(sign, bool):
        raise SchemaError("git.sign has invalid type")

    # file: list of tables
    files = _require(config, "file", list, "")
    if not files:
        raise SchemaError("file should not be empty")
    for idx, file_cfg in enumerate(files):
        if not isinstance(file_cfg, dict):
            raise SchemaError("file[%d] has invalid type" % idx)
        _require(file_cfg, "src", str, f"file[{idx}].")
        search = file_cfg.get("search", None)
        if search is not None and not isinstance(search, str):
            raise SchemaError(f"file[{idx}].search has invalid type")
        version_template = file_cfg.get("version_template", None)
        if version_template is not None and not isinstance(version_template, str):
            raise SchemaError(f"file[{idx}].version_template has invalid type")

    # field: optional list of tables
    fields = config.get("field", [])
    if not isinstance(fields, list):
        raise SchemaError("field has invalid type")
    for idx, field_cfg in enumerate(fields):
        if not isinstance(field_cfg, dict):
            raise SchemaError("field[%d] has invalid type" % idx)
        _require(field_cfg, "name", str, f"field[{idx}].")
        default = field_cfg.get("default", None)
        if default is not None and not isinstance(default, (str, int)):
            raise SchemaError(f"field[{idx}].default has invalid type")

    # hooks sections: hook (retro-compat), before_push, before_commit, after_push
    def _validate_hooks_section(section_name: str) -> None:
        value = config.get(section_name, [])
        if not isinstance(value, list):
            raise SchemaError(f"{section_name} has invalid type")
        for idx, hook in enumerate(value):
            if not isinstance(hook, dict):
                raise SchemaError(f"{section_name}[{idx}] has invalid type")
            _require(hook, "name", str, f"{section_name}[{idx}].")
            _require(hook, "cmd", str, f"{section_name}[{idx}].")

    for section in ["hook", "before_push", "before_commit", "after_push"]:
        _validate_hooks_section(section)

    github_url = config.get("github_url", None)
    if github_url is not None and not isinstance(github_url, str):
        raise SchemaError("github_url has invalid type")


def validate_config(cfg: Config) -> None:
    """Second pass of validation, using the Config class."""

    # Note: separated from validate_basic_schema to keep error
    # messages user friendly

    current_version = cfg.current_version

    validate_git_message_template(cfg.git_message_template)
    validate_git_tag_template(cfg.git_tag_template)

    match = cfg.version_regex.fullmatch(current_version)
    if not match:
        message = "Current version: %s does not match version regex" % current_version
        raise SchemaError(message)
    current_version_regex_groups = match.groupdict()

    for file_config in cfg.files:
        version_template = file_config.version_template
        if not version_template:
            continue
        validate_version_template(
            file_config.src,
            version_template,
            current_version_regex_groups,
        )

    for hook in cfg.hooks:
        validate_hook_cmd(hook.cmd)
